export interface AgentClarificationSuggestedAnswerWithDescription {
    answer: string;
    description: string;
}
export type AgentClarificationSuggestedAnswer = string | AgentClarificationSuggestedAnswerWithDescription;
export interface AgentClarificationQuestion {
    question: string;
    suggestedAnswers: readonly AgentClarificationSuggestedAnswer[];
}
export interface AgentClarificationAnswer {
    questionIndex: number;
    answer: AgentClarificationSuggestedAnswer;
}
/**
 * A content part of an assistant response message.
 *
 * Reasoning and tool inputs are internal to the agent: reasoning content is omitted and tool
 * calls only expose the tool name and input. Text parts contain the user-facing response.
 */
export type AgentResponseContentPart = {
    type: "reasoning";
} | {
    type: "text";
    text: string;
} | {
    type: "tool-call";
    toolName: string;
    input: unknown;
};
/**
 * An assistant message from an agent turn.
 *
 * A turn typically produces multiple messages: text emitted between tool calls is progress
 * narration, and the last message containing text is the agent’s final response.
 */
export interface AgentResponseMessage {
    role: "assistant";
    content: readonly AgentResponseContentPart[];
}
export interface AgentConversationCompletedResult {
    responseMessages: readonly AgentResponseMessage[];
}
export interface AgentConversationNeedsClarificationResult {
    clarificationQuestions: readonly AgentClarificationQuestion[];
}
export type StartAgentConversationResult = ({
    conversationId: string;
} & AgentConversationCompletedResult) | ({
    conversationId: string;
} & AgentConversationNeedsClarificationResult);
export type ContinueAgentConversationResult = AgentConversationCompletedResult | AgentConversationNeedsClarificationResult;
export type SubmitAgentClarificationResult = ContinueAgentConversationResult;
export interface SubmitAgentClarificationOptions {
    conversationId: string;
    answers: AgentClarificationAnswer[];
}
export interface RunSupervisorAgentCommandOptions {
    goal: string;
    /** Supervisor model id, optionally with eval-style reasoning effort suffix, e.g. `anthropic/claude-opus-4.6=low`. */
    model: string;
    /**
     * Inner Framer Agent model override. Defaults to `model` when omitted.
     *
     * Supports the same `model=effort` syntax. Omitting effort is equivalent to `none`.
     */
    framerAgentModel?: string;
    pagePath?: string;
    maxSteps?: number;
    /** When true, capture per-step (system, tools, messages) → response training rows for SFT. */
    captureTrainingData?: boolean;
}
export interface RunSupervisorAgentCommandResult {
    filename: string;
    archiveBase64: string;
    /** Training-data filename, present when `captureTrainingData` was set. */
    trainingDataFilename?: string;
    /** JSONL string with one training row per inner-agent step, present when `captureTrainingData` was set. */
    trainingDataJsonl?: string;
    /** Replay trace filename, present when the inner agent produced at least one model step. */
    traceFilename?: string;
    /** Replay trace JSON with system, tools, and final ModelMessage conversation. */
    traceJson?: string;
    /** Document fixture filename, always present after a completed run. */
    fixtureFilename: string;
    /** Document fixture JSON content (tree + code files). */
    fixtureContent: string;
}
export interface AgentTurnOptions {
    /**
     * Treat these nodes as the implicit selection for this agent turn.
     *
     * When provided, all node ids must exist. If a node is not currently loaded in the session, it may not be found.
     */
    selectionNodeIds?: readonly string[];
    /**
     * Attach images to this agent turn by URL.
     *
     * URLs can be external or existing Framer asset URLs. They will be ingested into the
     * project's assets if needed, then made available to the agent as trusted attachment URLs.
     *
     * Tip: if you have a local file (or bytes), upload it first (e.g. `framer.uploadImage(...)`) and
     * pass the returned asset URL here.
     */
    imageUrls?: readonly string[];
    /**
     * Attach files to this agent turn by URL.
     *
     * URLs can be external or existing Framer asset URLs. They will be ingested into the
     * project's assets if needed, then made available to the agent as file attachments.
     */
    fileUrls?: readonly string[];
}
export interface StartAgentConversationOptions extends AgentTurnOptions {
    /**
     * Target page path (e.g. `"/about"`). Defaults to the active page.
     */
    pagePath?: string;
}
export interface ContinueAgentConversationOptions extends AgentTurnOptions {
    /** Existing agent conversation to continue. */
    conversationId: string;
}
